96:  * source assignment is the preferred representation of it — the teacher can
97:  * retitle it and set a due date — so it overrides, and `resolveItemRoute` sends
98:  * it to the same destination the raw row would have used.
99:  */
100: export interface AssignedFeedSources {
101:   hw: ReturnType<typeof useStudentAssignments>['assignments'];
102:   ta: ReturnType<typeof useStudentTAAssignments>['assignments'];
103:   guided: GuidedRow[];
104:   activities: Awaited<ReturnType<typeof listActivityForStudent>>;
105:   items: ClassroomItem[];
106:   guidedEvidence?: Record<string, GuidedWorkEvidence>;
107:   homeworkEvidence?: Record<string, HomeworkWorkEvidence>;
108:   activityEvidence?: ReadonlySet<string>;
109:   assignmentWorkEvidence?: AssignmentWorkEvidence;
110:   assignmentEvidenceUnavailable?: boolean;
111:   activityEvidenceUnavailable?: boolean;
112:   /** Undefined until the source read succeeds; plan mirrors cannot stand in for it. */
113:   weeklyPlanStatusById?: Readonly<Record<string, WeeklyPlanItem['status']>>;
114: }
115: 
116: /**
117:  * The pure merge behind the hook, exported so the disjoint-feed and
118:  * duplicate-assignment rules can be tested without standing up five queries.
119:  */
120: export function buildAssignedRows({
121:   hw,
122:   ta,
123:   guided,
124:   activities,
125:   items,
126:   guidedEvidence = {},
127:   homeworkEvidence = {},
128:   activityEvidence = EMPTY_ACTIVITY_EVIDENCE,
129:   weeklyPlanStatusById,
130:   assignmentWorkEvidence,
131:   assignmentEvidenceUnavailable = false,
132:   activityEvidenceUnavailable = false,
133: }: AssignedFeedSources): AssignedTodoRow[] {
134:   {
135:     const byIdentity = new Map<string, AssignedTodoRow>();
136:     const put = (row: AssignedTodoRow) => byIdentity.set(studentWorkKey({ sourceTable: row.sourceTable, assignmentId: row.refId }), row);
137: 
138:     for (const a of hw) {
139:       // A set that is exactly one PrepTest section is sat, not worked through:
140:       // it opens on the section's directions page and the clock does the
141:       // rest. Finishing the run completes the row, so it must never carry a
142:       // "Mark done" the student could press without sitting it.
143:       const section = singleSectionOf(a.question_qids ?? []);
144:       put({
145:         key: `hw-${a.id}`,
146:         kind: 'homework',
147:         refId: a.id,
148:         sourceTable: 'homework_assignments',
149:         title: a.set_title || 'Homework',
150:         subtitle: `${a.question_qids?.length ?? 0} questions${a.score != null ? ` · ${Math.round(a.score)}%` : ''}`,
151:         status: homeworkWorkStatus(a, homeworkEvidence[a.id]),
152:         createdAt: a.created_at,
153:         dueAt: null,
154:         route: section ? sectionDirectionsRoute(a.id) : `/classroom/${encodeURIComponent(a.id)}`,
155:         selfCompleting: !!section,
156:         workSection: sectionFromQuestionIds(a.question_qids),
157:       });
158:     }
159: 
160:     for (const a of ta) {
161:       put({
162:         key: `ta-${a.id}`,
163:         kind: 'ta',
164:         refId: a.id,
165:         sourceTable: 'ta_assignments',
166:         title: a.title || 'From Joshua',
167:         subtitle: a.pdf_url ? 'PDF attached' : 'TA assignment',
168:         status: teacherWorkStatus(a),
169:         createdAt: a.assigned_at,
170:         dueAt: null,
171:         route: `/classroom/ta/${encodeURIComponent(a.id)}`,
172:       });
173:     }
174: 
175:     // Preserve every assignment instance, even when the teacher issued the
176:     // same drill twice. The assignment ID, not guided_drill_id, is identity.
177:     for (const g of guided) {
178:       put({
179:         key: `g-${g.id}`,
180:         kind: 'guided',
181:         refId: g.id,
182:         sourceTable: 'guided_drill_assignments',
183:         title: g.guided_drill?.title || 'Guided drill',
184:         subtitle: `${g.guided_drill?.question_count ?? '?'} questions${g.guided_drill?.estimated_minutes ? ` · ${g.guided_drill.estimated_minutes} min` : ''}`,
185:         status: guidedWorkStatus(g, guidedEvidence[g.id]),
186:         createdAt: g.assigned_at,
187:         dueAt: null,
188:         route: `/guided/${encodeURIComponent(g.id)}`,
189:         workSection: sectionFromQuestionIds(g.question_qids?.length ? g.question_qids : g.guided_drill?.question_qids),
190:       });
191:     }
192: 
193:     for (const a of activities) {
194:       put({
195:         key: `act-${a.id}`,
196:         kind: 'activity',
197:         refId: a.id,
198:         sourceTable: 'activity_assignments',
199:         title: a.title || 'Activity',
200:         subtitle: a.subtitle || 'Activity',
201:         status: activityWorkStatus(a, activityEvidence.has(a.id)),
202:         createdAt: a.created_at,
203:         dueAt: null,
204:         route: `/activities/${encodeURIComponent(a.id)}`,
205:         workSection: mergeWorkSections(sectionFromCitation(a.source_section), sectionFromMetadata(a.instructions)),
206:       });
207:     }
208: 
209:     for (const item of items) {
210:       const kind = WORK_ITEM_KIND[item.type];
211:       if (!kind) continue; // notes and recaps are reading material, not work
212:       // The plan item can be checked off independently of its classroom mirror.
213:       // A missing source (including a failed or pending read) cannot certify a
214:       // status, and a skipped task no longer belongs on an assigned-work list.
215:       const planStatus = kind === 'plan' && item.source_table === 'weekly_plan_items' && item.source_id
216:         ? weeklyPlanStatusById?.[item.source_id]
217:         : undefined;
218:       if (kind === 'plan' && (!planStatus || planStatus === 'skipped')) continue;
219:       const route = resolveItemRoute(item);
220:       if (!route) continue;
221:       const sourceTable = item.source_table ?? 'classroom_items';
222:       const refId = item.source_id ?? item.id;
223:       const identity = studentWorkKey({ sourceTable, assignmentId: refId });
224:       const existing = byIdentity.get(identity);
225:       // Completion wins over the mirror. A student who finished the underlying
226:       // assignment must not see it come back because the classroom_items row it
227:       // was mirrored into still says "assigned" — that is why finished work kept
228:       // reappearing on Home.
229:       const itemStatus = normalizeStatus(item.status);
230:       // Guided and written teacher assignments have their own persisted
231:       // completion/progress evidence. A stale or manually updated mirror must
232:       // not promote them merely because the page was opened or a button was
233:       // pressed outside the actual work flow.
234:       const sourceOwnsStatus = existing && (
235:         sourceTable === 'guided_drill_assignments' ||
236:         sourceTable === 'homework_assignments' ||
237:         sourceTable === 'ta_assignments' ||
238:         sourceTable === 'activity_assignments'
239:       );
240:       const status = kind === 'plan' && planStatus && planStatus !== 'skipped'
241:         ? planStatus
242:         : sourceOwnsStatus
243:         ? existing.status
244:         : itemStatus === 'completed' || existing?.status === 'completed' ? 'completed' : itemStatus;
245:       byIdentity.set(identity, {
246:         key: `ci-${item.id}`,
247:         kind,
248:         refId,
249:         sourceTable,
250:         title: item.title || existing?.title || 'Assigned work',
251:         // The item carries no question count, so keep the source row's subtitle
252:         // when there is one.
253:         subtitle: existing?.subtitle ?? item.description ?? '',
254:         status,
255:         createdAt: item.created_at,
256:         dueAt: item.due_at,
257:         // The mirror row was written before the section rule existed, so the
258:         // source row's directions route wins over the item's classroom link.
259:         route: existing?.selfCompleting ? existing.route : route,
260:         selfCompleting:
261:           (item.metadata_json as { kind?: string } | null)?.kind === 'timed_section' ||
262:           !!existing?.selfCompleting,
263:         briefing: readSectionBriefing(item.metadata_json) ?? undefined,
264:         workSection: mergeWorkSections(existing?.workSection, sectionFromMetadata(item.metadata_json)),
265:       });
266:     }
267: 
268:     // Open work first, then completed; newest within each bucket.
269:     return [...byIdentity.values()].map(row => {
270:       const family = row.sourceTable === 'guided_drill_assignments' ? 'guided' : row.sourceTable === 'homework_assignments' ? 'homework' : null;
271:       const uncertain = family
272:         ? assignmentEvidenceUnavailable || (assignmentWorkEvidence && assignmentProgressUnverified(assignmentWorkEvidence, family, row.refId))
273:         : row.sourceTable === 'activity_assignments' && activityEvidenceUnavailable;
274:       return uncertain && row.status === 'assigned' ? { ...row, progressUnverified: true } : row;
275:     }).sort((x, y) => {
276:       const s = (x.status === 'completed' ? 1 : 0) - (y.status === 'completed' ? 1 : 0);
277:       if (s !== 0) return s;
278:       return new Date(y.createdAt).getTime() - new Date(x.createdAt).getTime();
279:     });
280:   }
281: }
