283: /** @see buildAssignedRows — this hook only supplies it with live queries. */
284: export function useAssignedTodoFeed(): {
285:   rows: AssignedTodoRow[];
286:   loading: boolean;
287:   /** A read failed. Never report "nothing assigned" on a failed read. */
288:   failed: boolean;
289:   evidenceWarnings: string[];
290:   retry: () => void;
291: } {
292:   const { user } = useAuth();
293:   const userId = user?.id;
294:   const { assignments: hw, loading: hwLoading, error: hwError, refresh: hwRefresh } = useStudentAssignments();
295:   const { assignments: ta, loading: taLoading, error: taError, refresh: taRefresh } = useStudentTAAssignments();
296:   const itemsQuery = useClassroomItems();
297:   const hasPlanMirrors = itemsQuery.data?.some((item) => item.type === 'weekly_plan_task') ?? false;
298: 
299:   const { data: weeklyPlanStatusById, isFetching: planFetching, isError: planError, refetch: planRefetch } = useQuery({
300:     queryKey: ['weekly-plan', 'assigned-status', userId],
301:     enabled: !!userId && hasPlanMirrors,
302:     staleTime: 0,
303:     queryFn: async (): Promise<Record<string, WeeklyPlanItem['status']>> => {
304:       const { data, error } = await supabase
305:         .from('weekly_plan_items')
306:         .select('id,status')
307:         .eq('student_id', userId!);
308:       if (error) throw error;
309:       return Object.fromEntries((data ?? []).map(({ id, status }) => [id, status as WeeklyPlanItem['status']]));
310:     },
311:   });
312: 
313:   const { data: guided = [], isLoading: guidedLoading, isError: guidedError, refetch: guidedRefetch } = useQuery<GuidedRow[]>({
314:     queryKey: ['todo-feed:guided', user?.id],
315:     enabled: !!user,
316:     staleTime: 30_000,
317:     queryFn: async () => (await listGuidedForStudent(user!.id)) as GuidedRow[],
318:   });
319: 
320:   const { data: activities = [], isLoading: actLoading, isError: actError, refetch: actRefetch } = useQuery({
321:     queryKey: ['todo-feed:activity', user?.id],
322:     enabled: !!user,
323:     staleTime: 30_000,
324:     queryFn: async () => listActivityForStudent(user!.id),
325:   });
326: 
327:   const { data: assignmentEvidence, isLoading: evidenceLoading, isError: evidenceError, refetch: evidenceRefetch } = useQuery({
328:     queryKey: ['todo-feed:assignment-evidence', user?.id],
329:     enabled: !!user,
330:     staleTime: 5_000,
331:     queryFn: () => loadAssignmentWorkEvidence(user!.id),
332:   });
333:   const guidedEvidence = assignmentEvidence?.guided;
334:   const homeworkEvidence = assignmentEvidence?.homework;
335: 
336:   const activityIds = useMemo(() => activities.map((activity) => activity.id), [activities]);
337:   const { data: activityEvidence = EMPTY_ACTIVITY_EVIDENCE, isLoading: activityEvidenceLoading, isError: activityEvidenceError, refetch: activityEvidenceRefetch } = useQuery({
338:     queryKey: ['todo-feed:activity-evidence', user?.id, activityIds],
339:     enabled: !!user && !actLoading,
340:     staleTime: 5_000,
341:     queryFn: () => loadActivityWorkEvidence(user!.id, activityIds),
342:   });
343: 
344:   const items = useMemo(() => itemsQuery.data ?? [], [itemsQuery.data]);
345:   const rows = useMemo(
346:     () => buildAssignedRows({ hw, ta, guided, activities, items, guidedEvidence, homeworkEvidence, activityEvidence, weeklyPlanStatusById, assignmentWorkEvidence: assignmentEvidence, assignmentEvidenceUnavailable: evidenceError || !assignmentEvidence, activityEvidenceUnavailable: activityEvidenceError || activityEvidenceLoading }),
347:     [hw, ta, guided, activities, items, guidedEvidence, homeworkEvidence, activityEvidence, weeklyPlanStatusById, assignmentEvidence, evidenceError, activityEvidenceError, activityEvidenceLoading],
348:   );
349: 
350:   const retry = useMemo(
351:     () => () => {
352:       void hwRefresh();
353:       void taRefresh();
354:       void guidedRefetch();
355:       void evidenceRefetch();
356:       void activityEvidenceRefetch();
357:       void actRefetch();
358:       void itemsQuery.refetch();
359:       void planRefetch();
360:     },
361:     [hwRefresh, taRefresh, guidedRefetch, evidenceRefetch, actRefetch, activityEvidenceRefetch, itemsQuery, planRefetch],
362:   );
363: 
364:   const evidenceWarnings = assignmentEvidenceWarnings(assignmentEvidence);
365:   return {
366:     rows,
367:     evidenceWarnings,
368:     loading: rows.length === 0 && (hwLoading || taLoading || guidedLoading || evidenceLoading || actLoading || activityEvidenceLoading || itemsQuery.isLoading || (hasPlanMirrors && !weeklyPlanStatusById && !planError && planFetching)),
369:     failed: evidenceWarnings.length > 0 || !!hwError || !!taError || guidedError || evidenceError || actError || activityEvidenceError || itemsQuery.isError || planError,
370:     retry,
371:   };
372: }

