111:   const words = text.replace(/\s+/g, " ").trim().split(" ").filter(Boolean);
112:   if (words.length === 0) return "";
113:   return words.length <= 55 ? words.join(" ") : `${words.slice(0, 55).join(" ")}…`;
114: }
115: 
116: /** Below this, a flat list is easier to scan than a grouped one. */
117: const MONTH_GROUP_THRESHOLD = 12;
118: 
119: /**
120:  * Read notes bucketed by the month they were written, newest month first.
121:  * Input is already sorted newest-first by groupNotes, so insertion order is
122:  * the display order and no second sort is needed.
123:  */
124: function groupNotesByMonth<T extends { created_at: string }>(notes: T[]) {
125:   const buckets = new Map<string, { key: string; label: string; notes: T[] }>();
126:   for (const note of notes) {
127:     const date = new Date(note.created_at);
128:     const key = `${date.getFullYear()}-${date.getMonth()}`;
129:     let bucket = buckets.get(key);
130:     if (!bucket) {
131:       bucket = {
132:         key,
133:         label: new Intl.DateTimeFormat("en-CA", {
134:           month: "long",
135:           year: "numeric",
136:         }).format(date),
137:         notes: [],
138:       };
139:       buckets.set(key, bucket);
140:     }
141:     bucket.notes.push(note);
142:   }
143:   return [...buckets.values()];
144: }
