194: export function ClassroomItemView() {
195:   const { itemId } = useParams<{ itemId: string }>();
196:   const location = useLocation();
197:   const notesReturnTo = validateNotesReturnTo(new URLSearchParams(location.search).get("returnTo"));
198:   const navigate = useNavigate();
199:   const query = useClassroomItems();
200:   const item = React.useMemo(
201:     () => (query.data ?? []).find((candidate) => candidate.id === itemId) ?? null,
202:     [itemId, query.data],
203:   );
204: 
205:   const queryClient = useQueryClient();
206:   const { user } = useAuth();
207:   const readAttempts = React.useRef(new Set<string>());
208: 
209:   // Reconcile the originating account even when a quick Back unmounts this view.
210:   React.useEffect(() => {
211:     const viewerId = user?.id;
212:     if (!item || !viewerId || item.student_id !== viewerId || !NOTE_TYPES.has(item.type)) return;
213:     const attemptKey = `${viewerId}:${item.id}`;
214:     if (readAttempts.current.has(attemptKey)) return;
215:     readAttempts.current.add(attemptKey);
216:     void markNoteRead(item, viewerId)
217:       .then((readItem) => {
218:         if (!readItem) return;
219:         const readAt = readItem.metadata_json?.read_at;
220:         if (typeof readAt === 'string' && readAt) queryClient.setQueryData<ClassroomItem[]>(['classroom-items', viewerId], (rows) => rows?.map((row) => row.id === readItem.id ? { ...row, metadata_json: { ...row.metadata_json, read_at: readAt } } : row));
221:         void queryClient.invalidateQueries({ queryKey: ['classroom-items', viewerId] });
222:         void queryClient.invalidateQueries({ queryKey: ['notifications', viewerId] });
223:         void queryClient.invalidateQueries({ queryKey: ['notifications-unread-count', viewerId] });
224:       })
225:       .catch((error) => {
226:         readAttempts.current.delete(attemptKey);
227:         console.warn('Could not confirm note read state', error);
228:       });
229:   }, [item, queryClient, user?.id]);
230: 
231:   React.useEffect(() => {
232:     if (!item) return;
233:     // An item that IS its own page must not be redirected off itself. A
234:     // homework part from a session bundle now resolves to this very route, so
235:     // without this guard the effect would replace the page with the page.
236:     if (isSelfContainedItem(item)) return;
237:     if (
238:       item.type === "drill" ||
239:       item.type === "homework" ||
240:       item.type === "activity" ||
241:       item.type === "bootcamp_module" ||
242:       item.type === "weekly_plan_task" ||
243:       item.type === "practice_test"
244:     ) {
245:       const route = resolveItemRoute(item);
246:       if (route) navigate(route, { replace: true });
247:     }
248:   }, [item, navigate]);
249: 
250:   const assignmentContext = !!item && ["homework", "drill", "activity", "practice_test", "bootcamp_module", "weekly_plan_task"].includes(item.type);
251:   const safeHtml = React.useMemo(() => {
252:     const html = item?.content_html ?? "";
253:     return sanitizeClassroomHtml(assignmentContext ? rcAssignmentHtml(html, window.location.origin) : html);
254:   }, [item?.content_html, assignmentContext]);
255: 
256:   if (query.isLoading && !query.data) return <DetailLoading />;
257:   if (query.error) {
258:     return (
259:       <DetailError
260:         message="Could not load this classroom item."
261:         retry={() => void query.refetch()}
262:       />
263:     );
264:   }
265:   if (!item) {
266:     return (
267:       <>
268:         <DetailHeading
269:           date={new Date().toISOString()}
270:           kind="Classroom"
271:           title="This item is no longer available"
272:         />
273:         <button
274:           type="button"
275:           className="classroom-button"
276:           onClick={() => navigate("/classroom")}
277:         >
278:           Back to your room
279:         </button>
280:       </>
281:     );
282:   }
283: 
284:   if (
285:     NOTE_TYPES.has(item.type) &&
286:     item.content_html?.includes('<meta name="lsatu-interactive-lesson"')
287:   ) {
288:     return (
289:       <div className="w-full">
290:         <button
291:           type="button"
292:           className="classroom-button mb-4"
293:           onClick={() => navigate(notesReturnTo)}
294:         >
295:           Back to notes
296:         </button>
297:         <iframe
298:           title={`${item.title} interactive lesson`}
299:           srcDoc={item.content_html}
300:           sandbox="allow-scripts allow-forms"
301:           className="block w-full min-h-[calc(100dvh-7rem)] border-0"
302:         />
303:       </div>
304:     );
305:   }
306: 
307:   const content = (
308:     <>
309:       {/* `item.type.replace(/_/g," ")` printed the raw column value, so students
310:           read "note" and "smartboard recap". NOTE_KIND_LABELS gives each type a
311:           name a student would actually use. */}
312:       <DetailHeading
313:         date={item.created_at}
314:         kind={noteKind(item.type)}
315:         title={item.title}
316:       />
317:       {/* Authored content, not an empty state. It was inheriting
318:           .classroom-empty-copy, which is the class for "there is nothing here". */}
319:       {item.description ? (
320:         <p className="classroom-note-standfirst">{item.description}</p>
321:       ) : null}
322:       {/* Rendered, not printed. This was `<p>{item.content_markdown}</p>`, and
323:           the bodies arriving here are real markdown: the AI TA bundle writes
324:           `- [ ] `, `**n. prompt**` and `_Answer:_` out of `body_markdown`. With
325:           no `white-space` on `.classroom-prose p`, a recap reached the student
326:           as one run-on line with its own syntax showing. */}
327:       <ClassroomMarkdown assignmentContext={assignmentContext}>{item.content_markdown}</ClassroomMarkdown>
328:       {safeHtml ? (
329:         <article
330:           className="classroom-prose"
331:           dangerouslySetInnerHTML={{ __html: safeHtml }}
332:         />
333:       ) : null}
334:       {/* A note used to end in silence. This is the highest-intent moment on
335:           the surface: the student has just read something their coach wrote
336:           about them. "Ask" is the affordance CONTEXT.md already defines,
337:           labelled that way and never with the coach's name. The back link
338:           exists because the reading column was otherwise navigable only by
339:           browser back. */}
340:       {NOTE_TYPES.has(item.type) ? (
341:         <div className="classroom-detail-actions">
342:           <button
343:             type="button"
344:             className="classroom-button classroom-button-primary"
345:             onClick={() =>
346:               navigate(`/inbox?about=${encodeURIComponent(item.title)}`)
347:             }
348:           >
349:             Ask
350:           </button>
351:           <button
352:             type="button"
353:             className="classroom-button"
354:             onClick={() => navigate(notesReturnTo)}
355:           >
356:             Back to notes
357:           </button>
358:         </div>
359:       ) : null}
360:     </>
361:   );
362:   return NOTE_TYPES.has(item.type)
363:     ? <section className="my-work-notes-page classroom-note-reader">{content}</section>
364:     : content;
365: }
366: 
367: /**
368:  * The newest note, opened far enough to be worth landing on.
369:  *
370:  * The stage used to render a dateline, an <h1> and a one-line count into a
371:  * 720px column and stop, so the widest region of the page carried the least
372:  * information and read as a page that had failed to load. Principle 2 asks the
373:  * product to compute the next step rather than present a menu; the next step
374:  * here is almost always the note that just arrived.
375:  *
376:  * Deliberately not a card. The stage has no card around it, and a bordered box
377:  * holding the only content on the page would be a container for its own sake.
378:  */
379: function FeaturedNote({
380:   note,
381:   unread,
382: }: {
383:   note: ReturnType<typeof groupNotes>["unread"][number];
384:   unread: boolean;
385: }) {
386:   const navigate = useNavigate();
387:   const excerpt = React.useMemo(() => noteExcerpt(note), [note]);
388:   const open = () => navigate(`/classroom/item/${encodeURIComponent(note.id)}`);
389: 
390:   return (
391:     <section className="classroom-featured-note" aria-labelledby="featured-note-title">
392:       <p className="classroom-featured-note-meta">
393:         {unread ? "Newest, unread" : "Most recent"}
394:         <span aria-hidden="true"> · </span>
395:         {noteKind(note.type)}
396:         <span aria-hidden="true"> · </span>
397:         <time dateTime={note.created_at}>{formatClassroomDate(note.created_at)}</time>
398:       </p>
399:       <h2 className="classroom-featured-note-title" id="featured-note-title">
400:         {note.title}
401:       </h2>
402:       {excerpt ? <p className="classroom-featured-note-excerpt">{excerpt}</p> : null}
403:       <button
404:         type="button"
405:         className="classroom-button classroom-button-primary"
406:         onClick={open}
407:       >
408:         Read it
409:       </button>
410:     </section>
411:   );
412: }
