414: export function ClassroomRecapsView() {
415:   const query = useClassroomItems();
416:   const { unread, read } = groupNotes(query.data ?? []);
417:   const total = unread.length + read.length;
418:   // Unread first, because the reason to open this page is almost always
419:   // something that just arrived. Falls back to the newest read note so the
420:   // stage still says something once the student is caught up.
421:   const featured = unread[0] ?? read[0] ?? null;
422: 
423:   // The page promises two categories and the feed carries four types, none of
424:   // which the row showed. A session recap, an announcement and a board from a
425:   // session were indistinguishable until opened.
426:   const row = (note: (typeof unread)[number], isUnread: boolean) => ({
427:     key: note.id,
428:     title: note.title,
429:     meta: `${noteKind(note.type)} · ${shortDate(note.created_at)}`,
430:     route: `/classroom/item/${encodeURIComponent(note.id)}`,
431:     unread: isUnread,
432:   });
433: 
434:   return (
435:     <>
436:       {/* No dateline on an index. It printed `new Date()`, so it stamped the
437:           page with the day the student happened to visit while sitting in the
438:           slot that, on a note, holds the day Joshua wrote it. It was the one
439:           number on the page that did not trace to stored data. */}
440:       <h1 className="classroom-title">Notes and recaps</h1>
441:       {query.isLoading && !query.data ? <DetailLoading /> : null}
442:       {query.error ? (
443:         <DetailError
444:           message="Could not load your notes and recaps."
445:           retry={() => void query.refetch()}
446:         />
447:       ) : null}
448:       {/* The zero case is a state, not an absence. Without a branch here the
449:           page rendered a heading and stopped, which is the surface a brand new
450:           student is most likely to open first. It claims nothing that is not
451:           true: it says where recaps come from and stops.
452: 
453:           This used to say the wording was shared with RecapsSection "so the
454:           two places cannot drift". RecapsSection had no importers, and neither
455:           did pages/ClassroomRecaps or pages/ClassroomItem: all three predated
456:           this shell and nothing routed to them. Deleted 2026-09-09. The copy
457:           has one home, which is here. */}
458:       {!query.isLoading && !query.error && total === 0 ? (
459:         <p className="classroom-empty-copy">
460:           Notes and recaps from your sessions with Joshua will show up here.
461:         </p>
462:       ) : null}
463:       {!query.isLoading && !query.error && total > 0 ? (
464:         <>
465:           <p className="classroom-surface-lede">
466:             What Joshua writes for you after a session, plus anything he sends
467:             between them.
468:           </p>
469:           {featured ? (
470:             <FeaturedNote note={featured} unread={unread.length > 0} />
471:           ) : null}
472:           <StageIndexHint>
473:             {unread.length > 0
474:               ? `${unread.length} unread of ${total}.`
475:               : `All ${total} read.`}
476:           </StageIndexHint>
477:           {unread.length > 0 ? (
478:             <StageIndexList
479:               label="Unread notes and recaps"
480:               heading="Unread"
481:               items={unread.map((note) => row(note, true))}
482:             />
483:           ) : null}
484:           {/* Read notes group by month once the list is long enough that a flat
485:               run stops being scannable. At ~25 sessions a week this is measured
486:               in hundreds within a year, and Flagged and Wrong answers both got a
487:               filter while this list got nothing. Grouping beats a search box for
488:               a chronological archive: a student looks for "the one after the
489:               February session", not for a word. Below the threshold a flat list
490:               is clearer, so the headings stay out of the way. */}
491:           {read.length > MONTH_GROUP_THRESHOLD
492:             ? groupNotesByMonth(read).map((group) => (
493:                 <StageIndexList
494:                   key={group.key}
495:                   label={`Notes and recaps from ${group.label}`}
496:                   heading={group.label}
497:                   items={group.notes.map((note) => row(note, false))}
498:                 />
499:               ))
500:             : read.length > 0 ? (
501:               <StageIndexList
502:                 label="Notes and recaps you have read"
503:                 heading={unread.length > 0 ? "Read" : undefined}
504:                 items={read.map((note) => row(note, false))}
505:               />
506:             ) : null}
507:         </>
508:       ) : null}
509:     </>
510:   );
511: }
