641:   const [completing, setCompleting] = React.useState(false);
642:   const [downloading, setDownloading] = React.useState(false);
643:   const viewedRef = React.useRef<string | null>(null);
644: 
645:   React.useEffect(() => {
646:     if (!assignment || assignment.status !== "assigned") return;
647:     if (viewedRef.current === assignment.id) return;
648:     viewedRef.current = assignment.id;
649:     void markTAAssignmentViewed(assignment.id).then((result) => {
650:       if (result.ok) void query.refresh();
651:     });
652:   }, [assignment, query]);
653: 
654:   const safeHtml = React.useMemo(
655:     () => sanitizeClassroomHtml(rcAssignmentHtml(assignment?.content_html ?? "", window.location.origin)),
656:     [assignment?.content_html],
