718:         <article
719:           className="classroom-prose"
720:           dangerouslySetInnerHTML={{ __html: safeHtml }}
721:         />
722:       ) : null}
723:       {structured ? (
724:         <StructuredTAAssignmentWorkspace
725:           assignment={assignment}
726:           refresh={query.refresh}
727:         />
728:       ) : null}
