909: /* Drill landing workspace: The Reasoning Observatory.
910:    Scoped here so the official /drill question surface cannot inherit it.
911: 
912:    2026-08-01 reskin ("hyper-real imagery"): the page is now ivory-on-black with
913:    two photographic surfaces (a planet horizon behind the hero, an eclipse behind
914:    Today) doing all the accent work. There is no accent colour on this page — no
915:    blue, no amber, no gold. Every grid texture, radial wash and gradient tone map
916:    the old observatory carried has been removed; what is left is flat tinted
917:    black, hairline rings, glass, and the two images. */
918: /* .rc-page is the Reading Comprehension hub, which is its own route rather than
919:    a classroom stage but belongs to the same visual system. It hosts the ladder
920:    here rather than restating the values, so there is still one source. */
921: .classroom-root.classroom-root-drill,
922: .rc-page,
923: .drill-setup-preview {
924:   /* Ink. One ivory, stepped by opacity. The ladder is closed — if a value is not
925:      on it, it does not belong on this page. */
926:   --observatory-ink: var(--lsatu-text-on-dark);
927:   --observatory-ink-90: rgba(239, 237, 230, 0.9);
928:   --observatory-ink-85: rgba(239, 237, 230, 0.85);
929:   --observatory-ink-70: rgba(239, 237, 230, 0.7);
930:   --observatory-ink-62: rgba(239, 237, 230, 0.62);
931:   --observatory-ink-60: rgba(239, 237, 230, 0.6);
932:   --observatory-ink-55: rgba(239, 237, 230, 0.55);
933:   --observatory-ink-50: rgba(239, 237, 230, 0.5);
934: 
935:   /* Surfaces. Tinted blacks, never #000. */
936:   --observatory-surface-card: var(--lsatu-surface-dark);
937:   --observatory-surface-image: #050507;
938:   --observatory-glass: rgba(6, 6, 9, 0.55);
939:   --observatory-glass-soft: rgba(6, 6, 9, 0.5);
940:   --observatory-glass-row: rgba(6, 6, 9, 0.45);
941:   --observatory-well: rgba(0, 0, 0, 0.35);
942: 
943:   /* Rings and hairlines. The only borders on this page. */
944:   --observatory-hairline: rgba(239, 237, 230, 0.09);
945:   --observatory-ring: rgba(239, 237, 230, 0.1);
946:   --observatory-ring-glass: rgba(239, 237, 230, 0.12);
947:   --observatory-ring-quiet: rgba(239, 237, 230, 0.08);
948:   --observatory-ring-strong: rgba(239, 237, 230, 0.2);
949:   --observatory-ring-chip: rgba(239, 237, 230, 0.25);
950: 
951:   --observatory-shadow-card: 0 12px 32px rgba(0, 0, 0, 0.12);
952:   --observatory-shadow-image: 0 12px 32px rgba(0, 0, 0, 0.16);
953:   --observatory-shadow-glass: 0 10px 28px rgba(0, 0, 0, 0.22);
954: 
955:   /* Kept for the side rail, which is out of this redesign's scope and still
956:      draws its active dot from them. Nothing in the main column uses them. */
957:   --observatory-field: var(--lsatu-action-on-dark);
958:   --observatory-shell: var(--lsatu-surface-dark);
959:   --observatory-light-ink: var(--lsatu-text-on-dark);
960:   --observatory-muted: rgba(239, 237, 230, 0.55);
961:   --observatory-line: rgba(239, 237, 230, 0.09);
962:   --observatory-blue: #79c4ff;
963:   --observatory-amber: #ff8a3d;
964: 
965:   /* Spacing ladder. Every padding, margin and gap in the observatory resolves to
966:      one of these. Before it there were sixteen distinct values — 7, 10, 13, 14,
967:      18, 22, 28, 58px and more — which is not a system, it's an accumulation. */
968:   --observatory-space-1: 4px;
969:   --observatory-space-2: 8px;
970:   --observatory-space-3: 12px;
971:   --observatory-space-4: 16px;
972:   --observatory-space-5: 20px;
973:   --observatory-space-6: 28px;
974:   --observatory-space-7: 30px;
975: 
976:   /* Four radii, by role: a card, a panel sitting on a card, an inner block, a
977:      control. Pills and circles are categorical, not scale values. */
978:   --observatory-radius-shell: 20px;
979:   --observatory-radius-panel: 18px;
980:   --observatory-radius-inner: 16px;
981:   --observatory-radius-control: 14px;
982: 
983:   --observatory-text-label: 11px;
984:   --observatory-text-label-sm: 10px;
985:   --observatory-text-meta: 12px;
986:   --observatory-text-body: 13.5px;
987:   --observatory-text-control: 15px;
988:   --observatory-text-heading: 20px;
989:   --observatory-text-display: 44px;
990: 
991:   --observatory-track-label: 0.18em;
992:   --observatory-track-route: 0.16em;
993:   --observatory-track-chip: 0.14em;
994:   --observatory-track-display: -0.01em;
995: 
996:   --observatory-label-font: "JetBrains Mono", ui-monospace, monospace;
997:   --observatory-display-font: "Fraunces", ui-serif, Georgia, serif;
998: 
999:   /* Motion: 150-180ms, ease-out, transform and opacity only.
1000: 
1001:      Ease-out, not the standard ease-in-out. A curve that eases in spends its
1002:      opening barely moving, which is right for something leaving the screen and
1003:      wrong for a control answering a pointer. Measured on the two curves: at
1004:      10% of the duration the old cubic-bezier(0.4, 0, 0.2, 1) has covered 2.6%
1005:      of the distance and at 25% only 23.7%, so on a 160ms hover nothing visible
1006:      happens for the first 40ms and the control reads as slow. The quart curve
1007:      covers 34.7% and 68.9% at those points: it leaves immediately and settles.
1008:      No bounce or elastic anywhere on this surface. */
1009:   --observatory-ease: cubic-bezier(0.25, 1, 0.5, 1);
1010:   --observatory-motion: 160ms var(--observatory-ease);
1011: 
1012:   /* The stage the cards sit on is cream. The two controls that ride on it
1013:      directly (the section switch, the jump row) are inked for the stage, not
1014:      for the cards. Measured on #fbf8f3: ink 12.9:1, muted 5.3:1. */
1015:   --observatory-stage-well: var(--lsatu-canvas);
1016:   --observatory-stage-ink: var(--lsatu-ink);
1017:   --observatory-stage-muted: var(--lsatu-ink-muted);
1018:   --observatory-stage-hair: rgba(68, 64, 61, 0.09);
1019:   --observatory-stage-lit: var(--lsatu-action-on-dark);
1020: 
1021:   /* One focus treatment for every control on the black cards: a solid ivory
1022:      outline offset from the edge, 15:1 against the card. Inset variant for
1023:      full-bleed rows whose outline would be clipped by their container. */
1024:   --observatory-focus: rgba(239, 237, 230, 0.85);
1025:   --observatory-skeleton: rgba(239, 237, 230, 0.12);
1026: }
