256: function TeacherWorkspaceIndex() {
257:   const { search, hash } = useLocation();
258:   const params = new URLSearchParams(search);
259:   const ws = params.get("ws");
260:   const tab = params.get("tab");
261: 
262:   let target = (ws && LEGACY_WORKSPACE_ROOMS[ws]) || "/teacher/today";
263:   if (target === "/teacher/library" && tab) target = `/teacher/library/${tab}`;
264: 
265:   // The room is in the path now; everything else (student, thread, query) is
266:   // still context the target surface wants.
267:   params.delete("ws");
268:   params.delete("tab");
269:   params.delete("pane");
270:   const rest = params.toString();
271: 
272:   return <Navigate to={preserveRedirectLocation(target, rest, hash)} replace />;
273: }
