10: export default function MyWorkGate({ children }: { children: ReactNode }) {
11:   const { user, authReady } = useAuth();
12:   const permissions = useUserPermissions();
13:   const generalAccess = permissions.is_admin || permissions.has_classroom_access;
14:   const readingCenter = useReadingCenterAccess(!generalAccess);
15:   if (!authReady || permissions.loading || (!!user && !generalAccess && readingCenter.isPending)) {
16:     return <div role="status" className="student-destination-message">Checking assigned work access…</div>;
17:   }
18:   return <ProtectedRoute allowSignedIn>
19:     {generalAccess || readingCenter.allowed ? children : readingCenter.isError
20:       ? <div role="alert" className="student-destination-message">We could not verify access to assigned work. <button type="button" className="classroom-button" onClick={() => void readingCenter.refetch()}>Try again</button></div>
21:       : <LockedModule />}
22:   </ProtectedRoute>;
23: }

